                   HookOptions {
                       controller: Some(P1),
                       ..Default::default()
                   },
               );
               (animate(json_as(
                   json!({ "target": { "of": "instance", "instanceId": wing.id } }),
               ))
               .apply)(&mut ctx);
           });
